<script setup lang="ts">
const {t}=useI18n(),route=useRoute(),router=useRouter(),{bizErrorMessage}=useBizError(),{locationTypeLabel}=useOptionLabel()
const warehouse=useWarehouseStore(),staff=useStaffStore()
const ready=ref(false)
const data=ref<PaginationData|null>(null),summary=ref<any>(null),loading=ref(true),error=ref(''),keyword=ref(String(route.query.keyword||''))
let previousScope=String(warehouse.currentWarehouse?.id??useCookie('warehouse_id').value??'')
let generation=0
const go=(patch:Record<string,any>,keepPage=false)=>{const query:Record<string,any>={...route.query,...patch};if(!keepPage)delete query.page;for(const key of Object.keys(query))if(query[key]==null||query[key]==='')delete query[key];router.push({query})}
const load=async()=>{const seq=++generation;loading.value=true;error.value='';data.value=null;summary.value=null;ready.value=false;const current=await staff.getCurrentStaffInfo();if(seq!==generation)return;if(!current){error.value=t('common.validation.company-required');loading.value=false;return}ready.value=true;const result=await Promise.all([httpRequest<PaginationData>('/api/warehouse/inventory/by-location/items',{params:{...route.query,warehouse_id:warehouse.currentWarehouse?.id||undefined,per_page:50},onError:err=>{if(seq===generation)error.value=bizErrorMessage(err)}}),httpRequest<any>('/api/warehouse/inventory/by-location',{params:{...route.query,warehouse_id:warehouse.currentWarehouse?.id||undefined,per_page:1},onError:err=>{if(seq===generation)error.value=bizErrorMessage(err)}})]);if(seq===generation){data.value=result[0];summary.value=result[1]?.summary;loading.value=false}}
watch(()=>route.query,()=>{keyword.value=String(route.query.keyword||'');load()});onMounted(load);onBeforeUnmount(()=>generation++)
watch(()=>warehouse.currentWarehouse?.id,id=>{const scope=String(id??'');const changed=scope!==previousScope;previousScope=scope;if(changed&&(route.query.zone||route.query.shelf||Number(route.query.page)>1))go({page:undefined,zone:undefined,shelf:undefined,shelf_levels:undefined,shelf_separator:undefined,shelf_prefix_length:undefined});else load()})
useHead({title:()=>t('inventory.views.location')})
const columns=computed(()=>[{key:'location',label:t('nav.location')},{key:'goods',label:t('nav.goods'),wrap:true},{key:'lot',label:t('inventory.views.lot')},{key:'expiry',label:t('inventory.views.expiry')},{key:'quantity',label:t('common.fields.quantity'),type:'qty' as const,strong:true,keepZero:true},{key:'stock_type',label:t('ledger.stock-type')}])
</script>
<template><div class="w-location-inventory w-scope"><h1>{{t('nav.inventory')}}</h1><InventoryViewNav active="/inventory/by-location" /><WCard v-if="summary" flush><div class="w-location-summary"><div v-for="item in [{key:'quantity',label:t('goods.ui.onhand')},{key:'location_count',label:t('nav.location')},{key:'occupied_count',label:t('inventory.views.occupied')},{key:'empty_count',label:t('inventory.views.empty')}]" :key="item.key"><span>{{item.label}}</span><strong>{{summary[item.key]}}</strong></div></div></WCard><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="load">{{t('dn.list.retry')}}</WButton></template></WAlert>
 <WCard flush><form class="w-location-filters" @submit.prevent="go({keyword:keyword.trim()})"><WButton v-if="route.query.shelf" variant="text" @click="go({shelf:undefined,shelf_levels:undefined,shelf_prefix_length:undefined,shelf_separator:undefined})">{{t('capacity.clear-shelf',{shelf:String(route.query.shelf)})}}</WButton><WButton v-if="route.query.zone" variant="text" size="sm" @click="go({zone:undefined})">{{t('inventory-analysis.zone')}} {{route.query.zone}} &times;</WButton><WInput v-model="keyword" type="search" :placeholder="t('inventory.views.location-search')" :aria-label="t('common.search')" @change="go({keyword:keyword.trim()})"><template #prefix><WIcon name="search" :size="16" /></template></WInput><WFilterSelect :model-value="String(route.query.location_type||'')||null" :label="t('location.fields.location-type')" :options="['standard','damaged','return'].map(value=>({value,label:locationTypeLabel(value)}))" @change="value=>go({location_type:value})" /></form><WTable :columns="columns" :rows="data?.items||[]" :loading="loading" inset>
 <template #cell-location="{row}"><NuxtLink v-if="ready&&staff.hasPermission('location_read')" class="w-stock-link" :to="'/location/detail/'+row.location.id">{{row.location.code}}</NuxtLink><span v-else class="w-stock-link">{{row.location.code}}</span><span class="w-stock-sub">{{locationTypeLabel(row.location.location_type)}}</span></template><template #cell-goods="{row}"><NuxtLink v-if="ready&&staff.hasPermission('goods_read')" class="w-stock-link" :to="'/goods/detail/'+row.goods.id">{{row.goods.name}}</NuxtLink><span v-else class="w-stock-link">{{row.goods.name}}</span><span class="w-stock-sub">{{row.goods.code}}</span></template><template #cell-lot="{row}">{{row.lot?.lot_no||'—'}}</template><template #cell-expiry="{row}">{{row.lot?.expiry_date}}</template><template #cell-stock_type="{row}">{{t('ledger.types.'+row.stock_type)}}</template></WTable><footer><WPagination :page="Number(route.query.page)||1" :page-size="50" :total="data?.total" show-total @update:page="value=>go({page:value},true)" /></footer></WCard>
</div></template>
<style scoped>
.w-location-inventory{display:flex;flex-direction:column;gap:16px}.w-location-inventory h1{margin:0;font-size:24px;line-height:32px;font-weight:600}.w-location-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}.w-location-summary>div{padding:16px 20px;display:flex;flex-direction:column;gap:4px}.w-location-summary>div+div{border-left:1px solid var(--w-line)}.w-location-summary span{font-size:13px;color:var(--w-text-3)}.w-location-summary strong{font-size:24px;line-height:32px;font-weight:600}.w-location-filters{padding:12px 20px;display:flex;flex-wrap:wrap;gap:8px}.w-location-filters :deep(.w-input){max-width:320px}.w-location-inventory :deep(.w-table){min-width:800px;border-collapse:collapse}.w-location-inventory :deep(.w-table thead th){height:auto;padding:12px 12px 8px;line-height:18px}.w-location-inventory :deep(.w-table tbody td){padding:12px}.w-location-inventory :deep(th:first-child),.w-location-inventory :deep(td:first-child){padding-left:20px}.w-stock-link{font-weight:500;color:var(--w-text-1)}.w-stock-sub{display:block;font-size:12px;line-height:18px;color:var(--w-text-3)}.w-location-inventory footer{padding:12px 20px;border-top:1px solid var(--w-border)}@media(max-width:600px){.w-location-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.w-location-summary>div:nth-child(3){border-left:0}}
</style>
